    # Calls:
    # 1 - (403) POST:/permissions/sync
    # 2 - (204) POST:/permissions/sync
    # 3 - (401) POST:/auth/login
    # Found 1 potential fault of type-code 205
    @timeout_decorator.timeout(60)
    def test_17_post_on_login_authenticatedButWronglyToldNot(self):
        
        headers = {}
        headers["content-type"] = "application/json"
        body = " { " + \
            " \"username\" : \"viewer\", " + \
            " \"password\" : \"Viewer@123\", " + \
            " \"remember\" : true " + \
            " } "
        cookies_viewer_jar = requests \
                .post(self.baseUrlOfSut + "/auth/login", 
                    headers=headers, data=body, allow_redirects=False, verify=False).cookies
        cookies_viewer = requests.utils.dict_from_cookiejar(cookies_viewer_jar)
        
        headers = {}
        headers["content-type"] = "application/json"
        body = " { " + \
            " \"username\" : \"admin\", " + \
            " \"password\" : \"Truthy@123\", " + \
            " \"remember\" : true " + \
            " } "
        cookies_admin_jar = requests \
                .post(self.baseUrlOfSut + "/auth/login", 
                    headers=headers, data=body, allow_redirects=False, verify=False).cookies
        cookies_admin = requests.utils.dict_from_cookiejar(cookies_admin_jar)
        
        
        headers = {}
        headers['Accept'] = "*/*"
        res_0 = requests \
                .post(self.baseUrlOfSut + "/permissions/sync",
                    headers=headers, cookies=cookies_viewer, timeout=EM_HTTP_TIMEOUT_S, verify=False)
        
        assert res_0.status_code == 403
        assert "application/json" in res_0.headers["content-type"]
        assert res_0.json()["statusCode"] == 403
        assert res_0.json()["message"] == "exception.Forbidden resource"
        assert res_0.json()["error"] == "Forbidden"
        
        headers = {}
        headers['Accept'] = "*/*"
        res_1 = requests \
                .post(self.baseUrlOfSut + "/permissions/sync",
                    headers=headers, cookies=cookies_admin, timeout=EM_HTTP_TIMEOUT_S, verify=False)
        
        assert res_1.status_code == 204
        assert res_1.text == ''
        
        # Fault205. Wrongly Not Recognized as Authenticated.
        headers = {}
        headers["content-type"] = "application/json"
        body = {}
        body = " { " + \
            " \"username\" : \"viewer\", " + \
            " \"password\" : \"CrQX\", " + \
            " \"remember\" : false " + \
            " } "
        headers['Accept'] = "*/*"
        res_2 = requests \
                .post(self.baseUrlOfSut + "/auth/login",
                    headers=headers, cookies=cookies_admin, data=body, timeout=EM_HTTP_TIMEOUT_S, verify=False)
        
        assert res_2.status_code == 401
        assert "www-authenticate" not in res_2.headers
        assert "application/json" in res_2.headers["content-type"]
        assert res_2.json()["message"] == "Credential didn't match!"
        assert res_2.json()["code"] == 1014
        assert res_2.json()["statusCode"] == 401
        assert res_2.json()["error"] == True
    
    
